# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NEML SURESİ 19. AYET: HZ. SÜLEYMAN\'IN (AS) ŞÜKÜR DUASI</text>\n  <rect x="20" y="45" width="660" height="90" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e3a8a">«رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ</text>\n  <text x="350" y="102" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e3a8a">وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ»</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" fill="#1d4ed8">Okunuşu: "Rabbi evzi\'nî en eşküra ni\'meteke\'lletî en\'amte aleyye ve alâ vâlideyye ve en a\'mele sâlihan terdâhü ve edhılnî birahmetike fî ıbâdike\'s-sâlihîn."</text>\n\n  <rect x="20" y="148" width="660" height="92" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="170" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Duanın Türkçe Anlamı (Neml Suresi, 19. Ayet)</text>\n  <text x="350" y="194" text-anchor="middle" font-size="12" fill="#14532d">"Ey Rabbim! Beni; bana ve anne babama verdiğin nimetlere şükretmeye</text>\n  <text x="350" y="214" text-anchor="middle" font-size="12" fill="#14532d">ve razı olacağın salih ameller işlemeye yönelt (ilham et) ve beni rahmetinle</text>\n  <text x="350" y="232" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">salih kullarının arasına kat!"</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. SÜLEYMAN\'IN (AS) DUASINDAKİ ÜÇ TEMEL İSTEK</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Nimete Şükür Bilinci</text>\n  <text x="125" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">أَنْ أَشْكُرَ نِعْمَتَكَ</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#334155">Hem kendisine hem de</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#334155">anne-babasına (وَالِدَيَّ)</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#334155">verilen maddi-manevi</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" fill="#334155">nimetlerin farkında olup</text>\n  <text x="125" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">kalp, dil ve davranışla</text>\n  <text x="125" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">Allah\'a şükretmek.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Salih Amel İşlemek</text>\n  <text x="350" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">أَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#334155">Şükrün sözde kalmayıp</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#334155">Allah\'ın razı olacağı (تَرْضَاهُ)</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#334155">güzel, faydalı ve dürüst</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11" fill="#334155">davranışlara (salih amele)</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">dönüşmesi için Allah\'tan</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">başarı ve ilham istemek.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">3. İlahi Rahmet ve Salihler</text>\n  <text x="575" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#334155">Hükümdar ve peygamber</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#334155">olmasına rağmen kibre</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#334155">kapılmayıp, kurtuluşu</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11" fill="#334155">Allah\'ın rahmetinden (بِرَحْمَتِكَ)</text>\n  <text x="575" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">dileyerek salih kullar</text>\n  <text x="575" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">arasına katılmayı istemek.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE GENEL ÖZETİ: KUR\'AN-I KERİM\'İ TANIYALIM</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Kur\'an\'ın İsimleri ve Ana Konuları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• el-Furkân: Hak ile batılı ayıran</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• el-Hüdâ / en-Nûr: Doğru yolu gösteren / Aydınlatan</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• eş-Şifâ / ez-Zikr: Gönüllere şifa / Öğüt ve hatırlatma</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#881337">Beş Ana Konu:</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#334155">1. İnanç (İman) · 2. İbadet · 3. Ahlak</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" fill="#334155">4. Muamelat (Sosyal/Hukuki İlişkiler) · 5. Kıssalar</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ünitedeki Sure ve Dualarımız</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Âyetü\'l-Kürsî (Bakara Suresi, 255. Ayet):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Tevhid, el-Hayy ve el-Kayyûm isimleri, Allah\'ın</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" fill="#334155">sonsuz ilmi, kudreti ve kürsîsi (hükümranlığı).</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Hucurât Suresi (10-13. Ayetler):</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" fill="#334155">Müminlerin kardeşliği, gıybet, tecessüs ve zan yasağı.</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Neml Suresi 19. Ayet (Hz. Süleyman\'ın Duası):</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#334155">Anne-baba nimetine şükür, salih amel ve rahmet.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
